useGSAP(() => {
  const container = containerRef.current;
  const tl = gsap.timeline({
    scrollTrigger: {
      trigger: container,
      start: 'top 80%',
      end: 'bottom 20%',
      toggleActions: 'play reset play reverse',
    },
  });

  tl.to(title, { opacity: 1, duration: 1 })
    .to(paths, { drawSVG: '0% 100%', stagger: 0.3 }, '-=0.4');
}, { scope: containerRef });
